import{_ as a,C as o,o as d,c as n,j as t,a as s,E as i,ag as p}from"./chunks/framework.DMVuHR7L.js";const w=JSON.parse('{"title":"Dumpsys","description":"","frontmatter":{},"headers":[],"relativePath":"features/dumpsys.md","filePath":"features/dumpsys.md","lastUpdated":1778215360000}'),l={name:"features/dumpsys.md"};function m(u,e,h,g,c,f){const r=o("ThemeImage");return d(),n("div",null,[e[0]||(e[0]=t("h1",{id:"dumpsys",tabindex:"-1"},[s("Dumpsys "),t("a",{class:"header-anchor",href:"#dumpsys","aria-label":'Permalink to "Dumpsys"'},"​")],-1)),e[1]||(e[1]=t("p",null,[t("code",null,"dumpsys"),s(" is Android's general-purpose service introspection command — it'll happily print thousands of lines about a service's internal state. The Dumpsys widget wraps the most common services in "),t("strong",null,"presets"),s(", runs the underlying command, and renders the result as either parsed cards or the raw output.")],-1)),i(r,{"src-dark":"/img/features/dumpsys-default.png","src-light":"/img/features/dumpsys-default-light.png",alt:"Dumpsys tile"}),e[2]||(e[2]=p('<h2 id="presets" tabindex="-1">Presets <a class="header-anchor" href="#presets" aria-label="Permalink to &quot;Presets&quot;">​</a></h2><p>The pill row at the top of the widget chooses what to dump:</p><table tabindex="0"><thead><tr><th>Preset</th><th>Service</th><th>What you get</th></tr></thead><tbody><tr><td><strong>Battery</strong></td><td><code>battery</code></td><td>Charge state, level, voltage, temperature, plugged status.</td></tr><tr><td><strong>Memory</strong></td><td><code>meminfo</code></td><td>System memory summary, top RAM consumers, oom_adj buckets.</td></tr><tr><td><strong>CPU</strong></td><td><code>cpuinfo</code></td><td>Per-process CPU usage, load averages.</td></tr><tr><td><strong>GFX</strong></td><td><code>gfxinfo</code></td><td>Frame timing histogram, jank percentage, render thread stats.</td></tr><tr><td><strong>Wi-Fi</strong></td><td><code>wifi</code></td><td>Connected SSID + BSSID, signal strength, supplicant state, scan cache.</td></tr></tbody></table><p>Each preset has bespoke parser logic that picks out the fields most people actually look at.</p><h2 id="view-modes" tabindex="-1">View modes <a class="header-anchor" href="#view-modes" aria-label="Permalink to &quot;View modes&quot;">​</a></h2><p>A segmented control flips between two renderings:</p><ul><li><strong>Cards</strong> — parsed, named, and laid out for skimming. The most useful signals (battery temperature, meminfo summary, current SSID) get their own cards; less interesting fields collapse under a <em>more</em> fold.</li><li><strong>Raw</strong> — the verbatim output of <code>dumpsys &lt;service&gt;</code>. Useful for copying into a bug report or grepping for something the parser doesn&#39;t surface.</li></ul><p>The view mode is per-tile and persists.</p><h2 id="refresh" tabindex="-1">Refresh <a class="header-anchor" href="#refresh" aria-label="Permalink to &quot;Refresh&quot;">​</a></h2><p>The refresh icon re-runs the current preset. Output is <strong>not</strong> streamed — <code>dumpsys</code> takes a one-shot snapshot.</p><h2 id="per-widget-settings" tabindex="-1">Per-widget settings <a class="header-anchor" href="#per-widget-settings" aria-label="Permalink to &quot;Per-widget settings&quot;">​</a></h2><p>The cog opens a settings modal with:</p><ul><li><strong>Default preset.</strong> Which preset the widget mounts on.</li><li><strong>Default view.</strong> Cards or Raw.</li></ul><p>Two Dumpsys tiles can sit side by side with different presets pinned — one watching Battery, another watching GFX during a perf investigation.</p>',14))])}const b=a(l,[["render",m]]);export{w as __pageData,b as default};
